export function resolveSymbolFromSchema(symbol, schema) {
    const { data: rawSymbol, success, error: symbolError, } = schema.safeParse(symbol.raw);
    if (!success) {
        throw new Error(`Failed to parse '${symbol.name}'. Reason: ${symbolError.message}`);
    }
    return {
        ...symbol,
        ...rawSymbol,
    };
}
